function get_state_demographics_html($state) {
    global $wpdb;

    $data = $wpdb->get_row(
        $wpdb->prepare(
            "SELECT
                COUNT(*) AS districts,
                SUM(total_population) AS total_population,
                SUM(aanhpi_alone_combined) AS aanhpi_population
             FROM demographics_clean
             WHERE state = %s",
            $state
        )
    );

    if (!$data || $data->total_population <= 0) {
        return '<p>No demographic data available.</p>';
    }

    $total = (int) $data->total_population;
    $aanhpi = (int) $data->aanhpi_population;
    $percentage = ($aanhpi / $total) * 100;

    $stats = array(
        'Total Population' => number_format($total),
        'AANHPI Alone Population' => number_format($aanhpi),
        'AANHPI Alone Percentage' => number_format($percentage, 2) . '%'
    );

    $output = '<section class="demographics-section">';
    $output .= '<h3 class="section-title">Demographic Overview</h3>';
    $output .= '<div class="demographics-grid">';

    foreach ($stats as $label => $value) {
        $output .= '<div class="demographic-card">';
        $output .= '<div class="demographic-value">' . esc_html($value) . '</div>';
        $output .= '<div class="demographic-label">' . esc_html($label) . '</div>';
        $output .= '</div>';
    }

    $output .= '</div>';
    $output .= '<p class="demographics-source">Source: 2024 American Community Survey, 5-Year Estimates</p>';
    $output .= '</section>';

    return $output;
}

function get_congress_members_html($state) {
    global $wpdb;

    $state = strtoupper(sanitize_text_field($state));

    if (!preg_match('/^[A-Z]{2}$/', $state)) {
        return '<p>Invalid state.</p>';
    }

    $results = $wpdb->get_results(
        $wpdb->prepare(
            "SELECT * FROM `congressdb`
             WHERE state = %s
             AND name <> 'name'
             ORDER BY CAST(district AS UNSIGNED) ASC, name ASC",
            $state
        )
    );

    $senators = array();
    $representatives = array();

    foreach ($results as $person) {
        if (strcasecmp(trim($person->Seat), 'Senator') === 0) {
            $senators[] = $person;
        } else {
            $representatives[] = $person;
        }
    }

    $output = '<div class="congress-directory">';
    $output .= '<h2>' . esc_html($state) . ' Congressional Directory</h2>';

    $output .= get_state_demographics_html($state);

    if (empty($results)) {
        $output .= '<p>No congressional members found.</p>';
    }

    $sections = array(
        'U.S. Senators' => $senators,
        'U.S. House of Representatives' => $representatives
    );

    foreach ($sections as $title => $members) {
        if (empty($members)) {
            continue;
        }

        $output .= '<section class="congress-section">';
        $output .= '<h3 class="section-title">' . esc_html($title) . '</h3>';
        $output .= '<div class="members-grid">';

        foreach ($members as $person) {
            $output .= '<div class="representative">';

            $output .= '<div class="member-photo">';

            if (!empty($person->photo_url)) {
                $output .= '<img src="' . esc_url($person->photo_url) . '"
                    alt="' . esc_attr($person->name) . '"
                    loading="lazy"
                    onerror="this.style.display=\'none\'; this.nextElementSibling.style.display=\'block\';">';

                $output .= '<span style="display:none;">Photo unavailable</span>';
            } else {
                $output .= '<span>Photo unavailable</span>';
            }

            $output .= '</div>';

            $output .= '<h4 class="member-name">' . esc_html($person->name) . '</h4>';

            if (strcasecmp(trim($person->Seat), 'Senator') === 0) {
                $output .= '<p class="member-district">U.S. Senator</p>';
            } else {
                $district = trim((string) $person->district);

                if (strcasecmp($district, 'AL') === 0 ||
                    strcasecmp($district, 'At Large') === 0 ||
                    $district === '0' ||
                    $district === '00') {
                    $output .= '<p class="member-district">At-Large District</p>';
                } else {
                    $output .= '<p class="member-district">District ' . esc_html($district) . '</p>';
                }
            }

            $output .= '</div>';
        }

        $output .= '</div>';
        $output .= '</section>';
    }

    $output .= '</div>';

    return $output;
}

function display_congress_directory() {
    return '<div id="congress-results">
        <p>Select a state on the map to view its demographics and congressional representatives.</p>
    </div>';
}

add_shortcode('congress_directory', 'display_congress_directory');

function load_congress_members() {
    check_ajax_referer('congress_directory_nonce', 'nonce');

    $state = isset($_POST['state'])
        ? sanitize_text_field(wp_unslash($_POST['state']))
        : '';

    echo get_congress_members_html($state);

    wp_die();
}

add_action('wp_ajax_load_congress_members', 'load_congress_members');
add_action('wp_ajax_nopriv_load_congress_members', 'load_congress_members');

function congress_directory_ajax_script() {
    wp_register_script(
        'congress-directory-ajax',
        false,
        array(),
        '1.0',
        true
    );

    wp_enqueue_script('congress-directory-ajax');

    wp_add_inline_script(
        'congress-directory-ajax',
        'window.congressAjax = ' . wp_json_encode(array(
            'url' => admin_url('admin-ajax.php'),
            'nonce' => wp_create_nonce('congress_directory_nonce')
        )) . ';',
        'before'
    );
}

add_action('wp_enqueue_scripts', 'congress_directory_ajax_script');
